    // all BLOCK_M query rows in the tile, cutting redundant global memory traffic.
    for (int j = threadIdx.x; j < seqlen; j += blockDim.x) {
        const float4* Krow4 = (const float4*)(Kbase + (size_t)j*dim);
        float sum[BLOCK_M];
