        for (int j = 0; j < seqlen; j++) {
            const float4* Vrow4 = (const float4*)(Vbase + (size_t)j*dim);
            float4 vv = Vrow4[d8];
            const half2* vh = (const half2*)&vv;
            float2 vf0 = __half22float2(vh[0]);
            float2 vf1 = __half22float2(vh[1]);
            float2 vf2 = __half22float2(vh[2]);
            float2 vf3 = __half22float2(vh[3]);
            #pragma unroll
            for (int m = 0; m < actualM; m++) {
                float s = scores[m*seqlen + j];
                acc[m][0] += s * vf0.x;
                acc[m][1] += s * vf0.y;
                acc[m][2] += s * vf1.x;
                acc[m][3] += s * vf1.y;
                acc[m][4] += s * vf2.x;
                acc[m][5] += s * vf2.y;
                acc[m][6] += s * vf3.x;
                acc[m][7] += s * vf3.y;
            }
        }
        for (int m = 0; m < actualM; m++) {
            half2 outh[4];
            float invs = inv_sum[m];
            #pragma unroll
            for (int k = 0; k < 4; k++) {
                outh[k] = __floats2half2_rn(acc[m][2*k] * invs, acc[m][2*k+1] * invs);
            }
            ((float4*)(Obase + (size_t)m*dim))[d8] = *reinterpret_cast<float4*>(outh);
        }
    }
}
